effect.shader:
vec3 sat3v(vec3 c){ return clamp(c, vec3(0.0), vec3(1.0)); }
float lum(vec3 c){ return dot(c, vec3(0.2126, 0.7152, 0.0722)); }

// LAYER -> SCREEN. The lattice is built in layer space and every source read
// comes back through the layer transform.
// Positions are anchored on acScreenNorm - the engine's own screen position for
// this fragment - so the anchor never depends on the matrix. Only the DELTA goes
// through acLayerToScreen, and the w=0 multiply cancels the translation, so a
// layer-space offset becomes a screen-space offset exactly. fetchL(acLayerNorm)
// therefore returns texture2DCv(inputImg.texture, acScreenNorm), the engine idiom.
vec2 lpToScreen(vec2 v){ return acScreenNorm + (vec4(v - acLayerNorm, 0.0, 0.0) * acLayerToScreen).xy; }
vec4 fetchL(vec2 lp){ return texture2DCv(inputImg.texture, clamp(lpToScreen(lp), 0.0, 1.0)); }
vec3 strL(vec2 lp){ vec4 s = fetchL(lp); return s.rgb / max(s.a, 1e-4); }

float h21(vec2 p){ return fract(sin(dot(p + seed * 1.37, vec2(127.1, 311.7))) * 43758.5453123); }
float h22(vec2 p){ float n = h21(p); return fract(sin(n * 91.7 + 41.3) * 24634.6345); }

void main(){
vec2 lp  = acLayerNorm;
vec4 src = fetchL(lp);

float a  = max(src.a, 1e-4);
vec3 sc  = src.rgb / a;

float asp = acLayerSize.x / max(acLayerSize.y, 1.0);
vec2  lpA = vec2(lp.x * asp, lp.y);

float cells = max(acLayerSize.y / max(cellSize, 1.0), 1.0);
vec2  g = lpA * cells;
vec2  id = floor(g);
vec2  f  = fract(g);

// Mode flags hoisted out of the search loop - comparing a uniform nine times
// per pixel for nothing is the kind of thing that makes an effect feel heavy.
float hexOn   = 0.0;
float ringOn  = 0.0;
float bubOn   = 0.0;
if (mosaicMode >= 1 && mosaicMode <= 1) hexOn = 1.0;
if (mosaicMode >= 3 && mosaicMode <= 3) ringOn = 1.0;
if (mosaicMode >= 4) bubOn = 1.0;

// ---- nearest disc centre over the 3x3 neighbourhood --------------------
float bd  = 9.0;
vec2  bc  = vec2(0.5);
vec2  bid = id;
for (int j = -1; j <= 1; j++){
for (int i = -1; i <= 1; i++){
vec2 n = vec2(float(i), float(j));
vec2 c = id + n;
vec2 ctr = n + vec2(0.5);
if (hexOn > 0.5){
if (mod(c.y, 2.0) > 0.5) ctr.x += 0.5;
}
ctr += (vec2(h21(c), h22(c)) - 0.5) * 0.80 * jitter;
vec2 dv = ctr - f;
float d = dot(dv, dv);
if (d < bd){ bd = d; bc = ctr; bid = c; }
}
}

// Disc centre back into layer space, then read the layer there.
vec2 discA = (id + bc) / max(cells, 1.0);
vec2 discLp = vec2(discA.x / asp, discA.y);

vec3  dcol = strL(discLp);
float dl   = lum(dcol);
float hv   = h21(bid);

// Radius: base size scaled by a per-disc hash so the mosaic breathes, and
// driven a little by brightness so dark areas pack smaller.
float rad = sizeScale * 0.52 * (1.0 + (hv - 0.5) * sizeVar) * (0.72 + 0.56 * dl);
float d   = sqrt(bd);

// ---- ring / bubble structure -------------------------------------------
float rr = d / max(rad, 1e-4);
if (ringOn > 0.5){
float ring = 0.5 + 0.5 * cos(rr * max(ringCount, 1.0) * 6.2831853);
rad *= mix(1.0, 0.55 + 0.55 * ring, clamp(ringDepth, 0.0, 1.0));
}

float aa = 0.006 + 0.055 * clamp(edgeSoft, 0.0, 1.0);
float m  = 1.0 - smoothstep(rad - aa, rad + aa, d);

// Per-disc shading: a directional term plus a radial falloff so each disc reads
// as a dome rather than as a flat coin.
float la  = radians(rotate);
vec2  ldir = vec2(cos(la), sin(la));
float dom  = 1.0 - 0.55 * clamp(rr, 0.0, 1.0);
float dir  = 0.5 + 0.5 * dot(normalize(vec2(bc.x - f.x, bc.y - f.y) + vec2(1e-4)), ldir);
vec3  v    = dcol * mix(1.0, dom * (0.72 + 0.62 * dir), clamp(shade, 0.0, 1.0));

if (bubOn > 0.5){
// Bubbles: an off-centre specular plus a rim, which is what sells the glass.
vec2  hp   = (f - bc) - vec2(-0.30 * rad, -0.30 * rad);
float spec = exp(-dot(hp, hp) / max(rad * rad * 0.055, 1.0e-5));
float rim  = smoothstep(rad * 0.70, rad, d);
v += vec3(spec * 0.85) + vec3(rim * 0.22);
}

v = sat3v(v);

// Background between the discs: the source, pulled toward its own luminance so
// the discs read as the subject and the gaps as the ground.
vec3 bg = mix(sc * 0.35, vec3(lum(sc)) * 0.45, clamp(gapMix, 0.0, 1.0));

vec3  c   = mix(bg, v, m);
vec3  col = mix(sc, c, mixAmt);
float oA  = src.a * opacity;
gl_FragColor = vec4(col * oA, oA);
}
